def set_cell_paragraphs(cell, text: str) -> None:
    cell._tc.clear_content()
    for para in text.split("\n"):
        cell.add_paragraph(para)


def main() -> None:
    doc = Document(SOURCE)

    if len(doc.tables) >= 2:
        set_cell_paragraphs(doc.tables[1].cell(0, 0), BACKGROUND)

    if len(doc.tables) >= 3:
        set_cell_paragraphs(doc.tables[2].cell(0, 0), RESEARCH_CONTENT)
        set_cell_paragraphs(doc.tables[2].cell(1, 0), IMPLEMENTATION)
        set_cell_paragraphs(doc.tables[2].cell(2, 0), EXPECTED)

    doc.save(OUTPUT)
    print(f"saved={OUTPUT}")


if __name__ == "__main__":
    main()
